8b7c4bbab0baacb523303342889bbb66db74d807:
query ListStoryboards($projectId: ID!) {
  storyboards(projectId: $projectId) {
    id
    projectId
    title
    aspectRatio
    resolution
    durationSeconds
    numVariations
    createdAt
    updatedAt
  }
}

b683e586c1f15aec4ffa5beb48bcaf1880676709:
query ListProjects {
  projects {
    id
    title
    description
    createdAt
    updatedAt
  }
}

